function parseJson(s) {
  if (!s) return null;
  let t = String(s).trim().replace(/^```json\s*/i, '').replace(/```$/g, '').trim();
  const i = t.indexOf('{'); const j = t.lastIndexOf('}');
  if (i >= 0 && j > i) t = t.substring(i, j+1);
  try { return JSON.parse(t); } catch(e) { return null; }
}

let dec = parseJson(rawText);
if (!dec) {
  // Parse falhou - tentar extrair so o campo resposta via regex (fallback)
  let respFallback = '';
  try {
    const m = rawText.match(/"resposta"\s*:\s*"((?:[^"\\]|\\.)*)"/);
    if (m) respFallback = m[1].replace(/\\"/g,'"').replace(/\\n/g,' ').trim();
  } catch(e) {}
  // Se conseguiu pegar resposta natural via regex, usa. Senao, deixa simples.
  dec = { acao: 'apenas_responder', parametros: {}, resposta: respFallback || 'Pode mandar de novo? Nao consegui te ouvir direito.' };
}
// Coercao defensiva: campos do Gemini podem vir com tipo inesperado
