  const r = $input.first()?.json;
  if (r && r.id) {
    const prazoTxt = r.prazo ? ` (prazo ${fmtDate(r.prazo)})` : '';
    textoResposta = dec.resposta || `Anotei como tarefa #${r.id}${prazoTxt}. Vou te cobrar.`;
  }
}
if (acao === 'marcar_tarefa_feita') {
  const r = $input.first()?.json;
  if (r && r.id) textoResposta = dec.resposta || `Boa, marquei como feita.`;
}
if (acao === 'cancelar_tarefa') {
  const r = $input.first()?.json;
  if (r && r.id) textoResposta = dec.resposta || `Cancelei.`;
}
if (acao === 'adiar_tarefa') {
  const r = $input.first()?.json;
  if (r && r.id) textoResposta = dec.resposta || `Ok, adiado.`;
}

if (acao === 'listar_contas') {
  const rows = $input.all().map(i => i.json).filter(r => r && r.descricao && r.venc);
  if (!rows.length) textoResposta = 'Nenhuma conta pendente.';
  else {
    const total = rows.reduce((s,r)=> s + Number(r.valor||0), 0);
    textoResposta = 'Contas a pagar:\n' + rows.map((r,i)=>{
      const v = r.valor ? ' ' + fmtMoney(r.valor) : '';
      const atr = r.atrasada ? ' (ATRASADA)' : '';
      const rec = r.recorrencia ? ' ['+r.recorrencia+']' : '';
      return `${i+1}. #${r.id} ${r.descricao}${v} - vence ${r.venc}${atr}${rec}`;
    }).join('\n') + (total ? `\n\nTotal pendente: ${fmtMoney(total)}` : '');
  }
}
if (acao === 'registrar_conta') {
  const rows = $input.all().map(i => i.json).filter(r => r && r.id && r.venc);
  if (rows.length === 1) {
    const r = rows[0];
    textoResposta = dec.resposta || `Anotei: ${r.descricao}${r.valor ? ' de '+fmtMoney(r.valor) : ''}, vence ${r.venc}. Te aviso perto do vencimento.`;
  } else if (rows.length > 1) {
    textoResposta = (dec.resposta ? dec.resposta + '\n\n' : '') + 'Cadastradas:\n' + rows.map(r => `  #${r.id} ${r.descricao}${r.valor ? ' '+fmtMoney(r.valor) : ''} (vence ${r.venc})`).join('\n');
  }
}
if (acao === 'marcar_conta_paga') {
  textoResposta = dec.resposta || 'Marquei como paga e ja lancei na planilha.';
}
if (acao === 'cancelar_conta') {
  const r = $input.first()?.json;
  if (r && r.id) textoResposta = dec.resposta || `Cancelei: ${r.descricao}.`;
}
if (acao === 'minha_agenda') {
  const r = $input.first()?.json;
  if (r) {
    function pj(v){ if (typeof v === 'string') { try { return JSON.parse(v); } catch(e){ return []; } } return v || []; }
    const reunioes = pj(r.reunioes), lembretes = pj(r.lembretes), tarefas = pj(r.tarefas), contas = pj(r.contas), rotina = pj(r.rotina);
    const per = r.periodo === 'amanha' ? 'amanha' : (r.periodo === 'semana' ? 'da semana' : 'de hoje');
    let s = [];
    if (reunioes.length) s.push('*Reunioes:*\n' + reunioes.map(x => `  ${x.hora} - ${x.nome}${x.assunto ? ' ('+x.assunto.substring(0,50)+')' : ''}`).join('\n'));
    if (lembretes.length) s.push('*Lembretes:*\n' + lembretes.map(x => `  ${x.hora} - ${x.descricao}`).join('\n'));
    if (contas.length) s.push('*Contas a pagar:*\n' + contas.map(x => `  #${x.id} ${x.descricao}${x.valor ? ' '+fmtMoney(x.valor) : ''} (${x.venc})`).join('\n'));
    if (tarefas.length) s.push('*Tarefas:*\n' + tarefas.map(x => `  #${x.id} ${x.titulo}${x.prazo ? ' (ate '+x.prazo+')' : ''}`).join('\n'));
    if (rotina.length) s.push('*Rotina de casa:*\n' + rotina.map(x => `  ${x}`).join('\n'));
    textoResposta = s.length ? `Agenda ${per}:\n\n` + s.join('\n\n') : `Nada na agenda ${per}. Livre!`;
  }
}
if (acao === 'cancelar_lembrete') {
  const r = $input.first()?.json;
  if (r && r.id) textoResposta = dec.resposta || `Cancelei o lembrete: ${r.descricao}.`;
  else if (!passoFalhou) textoResposta = 'Nao achei esse lembrete pendente. Manda "quais lembretes tenho" pra ver a lista.';
}
if (acao === 'enviar_agora' || acao === 'confirmar_envio') {
  const status = $input.first()?.json?.status || $input.first()?.json?.statusCode;
  if (status && String(status).match(/^[45]/)) textoResposta = `Tive problema ao mandar: ${status}.`;
}
if (acao === 'enviar_com_confirmacao') {
  const r = $input.first()?.json;
  if (r && r.id && !dec.resposta) {
    textoResposta = `Deixei o envio #${r.id} preparado. Manda 'confirma' que eu disparo, ou 'cancela'.`;
  }
}
if (acao === 'cancelar_envio') {
  textoResposta = dec.resposta || 'Cancelado.';
}

// Fallback final: resposta nunca vazia
if (!textoResposta || !String(textoResposta).trim()) {
  const fb = {
    agendar_reuniao: 'Boa, vou ver a agenda do Thiago e te confirmo o horario. Qualquer coisa me chama.',
    qualificar_lead: 'Anotado. Vou passar pro Thiago e te retorno.',
    notificar_thiago: 'Passei pro Thiago, ele te responde.',
    encaminhar: 'Vou te direcionar com quem cuida disso.',
    apenas_responder: 'Certo.'
  };
  textoResposta = fb[acao] || 'Certo, anotado.';
}

return [{
  json: {
    sender_numero: dec.sender_numero,
    texto_original: dec.texto_original,
    resposta_final: textoResposta,
    facts_novos: dec.facts_novos || [],
    envio_pendente_id: dec.envio_pendente_id || null,
    envio_falhou: passoFalhou,
    acao: dec.acao
  }
}];

// Monta SQL combinado: INSERT memoria + INSERT facts + UPDATE envio pendente
const frf = $('Formatar Resposta Final').first().json;
const esc = s => String(s == null ? '' : s).replace(/'/g, "''");

const sender = frf.sender_numero || '';
const texto_user = esc(frf.texto_original || '');
const resposta = esc(frf.resposta_final || '');
const facts_novos = Array.isArray(frf.facts_novos) ? frf.facts_novos : [];
const envio_id = frf.envio_pendente_id;
const acao = frf.acao || '';

let sql_parts = [];

// 1. Conversa
sql_parts.push(`INSERT INTO giulia_memoria (from_numero, role, content, metadata) VALUES ('${esc(sender)}', 'user', '${texto_user}', NULL), ('${esc(sender)}', 'assistant', '${resposta}', NULL);`);

// 2. Facts novos sobre o Thiago
for (const f of facts_novos) {
  if (!f || !f.fact) continue;
  const cat = f.categoria ? `'${esc(f.categoria)}'` : 'NULL';
  sql_parts.push(`INSERT INTO giulia_facts (about_numero, fact, categoria, fonte) VALUES ('${esc(sender)}', '${esc(f.fact)}', ${cat}, 'conversa') ON CONFLICT (about_numero, fact) DO UPDATE SET atualizado_em = NOW(), ativo = TRUE;`);
}

// 3. confirmar_envio: marca enviado OU erro conforme resultado real do envio
if (acao === 'confirmar_envio' && envio_id) {
  const st = frf.envio_falhou ? 'erro' : 'enviado';
  sql_parts.push(`UPDATE giulia_envios_pendentes SET status = '${st}', enviado_em = NOW() WHERE id = ${parseInt(envio_id,10)};`);
}

return [{
  json: {
    final_sql: sql_parts.join('\n')
  }
}];

// Se sender esta na tabela engano (ativo, nao expirou), IGNORA a msg.
// Marcar_engano ja avisa na 1a interacao (msg que disparou), entao todas as proximas sao ignoradas.
const engano = items.filter(i => i.json && i.json.numero);
if (engano.length > 0) {
  // Ja na tabela - corta o pipeline
  return [];
}
// Passa adiante o estado original
const prev = $('Validar Mensagem').first().json;
return [{ json: prev }];

// Anexa base64 + url da imagem ao estado da mensagem
const prev = $('Validar Mensagem').first().json;
const urlResp = $('Baixar Imagem UAZAPI').first().json || {};
const current = $input.first().json || {};

const b64 = current.imagem_b64_extraida || '';
const mime = urlResp.mimetype || prev.imagem_mime || 'image/jpeg';
const fileURL = urlResp.fileURL || '';

return [{
  json: {
    ...prev,
    imagem_base64: b64,
    imagem_mime: mime,
    imagem_url: fileURL,
    imagem_download_falhou: !b64
  }
}];

// Se o INSERT nao retornou row E a msg tem id, e um retry duplicado -> ignora
const prev = $('Validar Mensagem').first().json;
if (!prev.message_id) return [{ json: prev }]; // sem id, nao da pra dedupar - passa
const inserted = items.filter(i => i.json && i.json.message_id);
if (!inserted.length) return []; // duplicado - corta o pipeline
return [{ json: prev }];
